// Decide whether this product update needs a stock alert. Each product is announced once per level
// (low, then out of stock) and is announced again only after its stock recovered above the threshold.
const cfg = $('Config').first().json;
const p = $('Product updated').first().json;
if (!p || !p.id) return [];

const threshold = Number.isFinite(Number(cfg.threshold)) ? Number(cfg.threshold) : 5;
const state = $getWorkflowStaticData('global');
state.alerted = state.alerted || {};
const key = String(p.id);

// Stock is only tracked as a number when "Manage stock" is on for the product.
const qty = p.manage_stock && p.stock_quantity !== null && p.stock_quantity !== undefined ? Number(p.stock_quantity) : null;
const isOut = p.stock_status === 'outofstock' || (qty !== null && qty <= 0);
const isLow = qty !== null && qty <= threshold;

if (!isOut && !isLow) {
  delete state.alerted[key]; // stock recovered: allow a new alert next time
  return [];
}

const level = isOut ? 'out' : 'low';
if (state.alerted[key] === level) return [];
state.alerted[key] = level;

// Keep the remembered list bounded.
const keys = Object.keys(state.alerted);
if (keys.length > 2000) keys.slice(0, keys.length - 2000).forEach((k) => delete state.alerted[k]);

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const site = String(cfg.siteUrl || '').replace(/\/+$/, '');
const editUrl = site + '/wp-admin/post.php?post=' + encodeURIComponent(p.id) + '&action=edit';

const lines = [
  (isOut ? '<b>Out of stock</b>' : '<b>Low stock</b>') + ': ' + esc(p.name),
  p.sku ? 'SKU: ' + esc(p.sku) : null,
  isOut ? 'Stock: 0' : 'Stock left: ' + qty + ' (alert at ' + threshold + ' or less)',
  p.backorders && p.backorders !== 'no' ? 'Backorders: ' + esc(p.backorders) : null,
  '<a href="' + esc(editUrl) + '">Edit product</a>',
].filter(Boolean);

return [{ json: { message: lines.join('\n'), productId: p.id, level } }];
